import { readFileSync } from 'node:fs';
import { createLuziaHandler, loadCompiledKnowledgeBase } from 'luzia-core';

// Generated by `luzia build`, which the `build` script runs before Vercel
// deploys this function (vercel.json ships it with the function).
const compiledKnowledgeBase = JSON.parse(
  readFileSync(new URL('../.luzia/knowledge-base.json', import.meta.url), 'utf8'),
);

// The chat model is read from LUZIA_CHAT_PROVIDER / LUZIA_CHAT_MODEL and the
// provider's API key (e.g. ANTHROPIC_API_KEY), all server-side only. Once the
// Knowledge Base has files besides the Core and Instructions, the embeddings
// model is read from LUZIA_EMBEDDING_PROVIDER / LUZIA_EMBEDDING_MODEL.
const handler = createLuziaHandler({
  knowledgeBase: loadCompiledKnowledgeBase(compiledKnowledgeBase),
  // The portfolio lives on another origin, so it must be allowed explicitly.
  // Replace these with your portfolio's origins (scheme + host, no path).
  // Leave `allowedOrigins` out to read LUZIA_ALLOWED_ORIGINS instead.
  allowedOrigins: ['https://jamie.example.com', 'https://www.jamie.example.com'],
});

// A Vercel Function with the Web `Request` / `Response` signature.
export const POST = handler;
// Answers CORS preflight from the allowed origins.
export const OPTIONS = handler;
// Tells the widget who luzIA talks about (the name in your Core), for its greeting.
export const GET = handler;
